"""Versioned native standing Sprite Editor import."""
from pathlib import Path
root=Path(__file__).resolve().parents[2]
t=(root/'Tools/Validation/ImportArmedGrip20261001.cs').read_text(encoding='utf-8')
t=t.replace('ImportArmedGrip20261001','ImportWeaponStanding20261001').replace('ArmedGripV3','WeaponStandingV1').replace('armed-grip-v3','weapon-standing-v1').replace('native-import-v3.json','standing-import-v1.json')
a=t.index('        var code=new StringBuilder(')
t=t[:a]+r'''        var code=new StringBuilder("// Six separate native standing profiles and short returns, exact original breathing/gait/head. Generated by ImportWeaponStanding20261001.\nusing UnityEngine;\nnamespace RuinRunner\n{\n public static class WeaponStandingFrames\n {\n");
        code.Append(" public const string Root=\"External/SscaryMaleCombat/WeaponStandingV1\";\n public const int UniqueSpriteCount=").Append(paths.Count).Append(";\n public const float ReturnSeconds=.14f;\n private static Sprite[] frames;\n");
        code.Append(" private static readonly int[] Cells={");foreach(var cell in cells)code.Append(cell).Append(',');code.Append("};\n");
        code.Append(" private static readonly Vector2[] Hands={");foreach(var h in hands)code.Append("new Vector2(").Append(h.x.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append("f,").Append(h.y.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append("f),");code.Append("};\n");
        code.Append(" private static readonly bool[] Behind={");foreach(var value in behind)code.Append(value?"true,":"false,");code.Append("};\n");
        code.Append(" public static void Preload(){if(frames!=null)return;frames=new Sprite[UniqueSpriteCount];for(int i=0;i<frames.Length;i++)frames[i]=IndividualArt.Sprite(Root+\"/\"+i.ToString(\"D5\"));}\n");
        code.Append(" public static int Profile(WeaponFamily f)=>f==WeaponFamily.Dagger?0:f==WeaponFamily.Longsword||f==WeaponFamily.Katana?1:f==WeaponFamily.Mace||f==WeaponFamily.Greatsword?2:f==WeaponFamily.Bow?3:f==WeaponFamily.Pistol?4:5;\n");
        code.Append(" public static Sprite Sample(int profile,int d,int variant,int key,out Vector2 h,out bool b){Preload();int slot=((Mathf.Clamp(profile,0,5)*8+Mathf.Clamp(d,0,7))*16+Mathf.Clamp(variant,0,15))*9+Mathf.Clamp(key,0,8);h=Hands[slot];b=Behind[slot];return frames[Cells[slot]];}\n");
        code.Append(" public static float Angle(int profile,float progress,Vector2 aim)=>(profile==0?-10:profile==1?20:profile==2?38:0)*(aim.x<0?-1:1)*Mathf.SmoothStep(0,1,progress);\n }\n}\n");
        File.WriteAllText("Assets/RuinRunner/Runtime/Player/WeaponStandingFrames.cs",code.ToString(),new UTF8Encoding(false));
        File.WriteAllText("ArtDirection/Review-20261001/weapon-carry/standing-import-v1.json",new JObject{{"uniqueSprites",paths.Count},{"sampleSlots",cells.Count},{"scope",data["scope"]},{"frames",rows}}.ToString(),new UTF8Encoding(false));
        AssetDatabase.SaveAssets();AssetDatabase.Refresh();return paths.Count+" separate standing native images; "+cells.Count+" original breathing/gait/short return combinations.";
    }
}
'''
(root/'Tools/Validation/ImportWeaponStanding20261001.cs').write_text(t,encoding='utf-8')
print('Generated native six-profile standing importer; preserve original sprites, data-provider pivots only.')

